function getOrderTotal(order: any): number {
  if (!order || !order.customerId) return 0;
  const customer = db.findCustomer(order.customerId);
  // later we assume order.customerId exists and use order.totalAmount
  return customer.discount * order.totalAmount;
}

class PaymentService {
  constructor(private config: any) {
    // config is stored but not validated here
  }

  async processPayment(payload: any) {
    // assumes config.gatewayKey exists and works
    const client = new GatewayClient(this.config.gatewayKey);
    return client.charge(payload.amount);
  }
}

// Version A: validate at public API boundary
function createUserA(data: any) {
  if (!data.email) throw new Error('email required');
  if (!isValidEmail(data.email)) throw new Error('invalid email');
  db.insert({ email: data.email, name: data.name || '' });
}

// Version B: validate deep inside downstream behavior
function createUserB(data: any) {
  db.insert({ email: data.email, name: data.name || '' });
  sendWelcomeEmail(data.email.toLowerCase());
}
